def longest(a: list[int], b: list[int]) -> list[int]:
    """Return the longer of a and b; a is returned when lengths are equal."""
    if len(b) > len(a):
        return b
    return a


def test_longer_second_list_wins() -> None:
    assert longest([1], [2, 3]) == [2, 3]


def test_longer_first_list_wins() -> None:
    assert longest([1, 2, 3], [4]) == [1, 2, 3]


def test_tie_returns_first() -> None:
    a = [1, 2]
    b = [3, 4]
    assert longest(a, b) is a


def test_empty_first_with_nonempty_second() -> None:
    assert longest([], [5]) == [5]


def test_both_empty_returns_first() -> None:
    a: list[int] = []
    b: list[int] = []
    assert longest(a, b) is a
